  "group flex items-center justify-between gap-3 rounded-xl px-3 py-2.5 text-left transition-colors hover:bg-surface focus-visible:bg-surface focus-visible:outline-none";

export function SearchDialog({ open, onOpenChange, sections }: SearchDialogProps) {
  const [query, setQuery] = useState("");
  const q = query.trim().toLowerCase();

  const sectionHits = useMemo(
    () => sections.filter((s) => s.label.toLowerCase().includes(q)),
    [sections, q],
  );
  const productHits = useMemo(
    () =>
      products.filter((p) =>
        [p.name, p.category, p.tagline, p.cardDesc].some((t) => t.toLowerCase().includes(q)),
      ),
    [q],
  );

  const close = () => {
    onOpenChange(false);
    setQuery("");
  };

  return (
    <Dialog open={open} onOpenChange={(next) => (next ? onOpenChange(true) : close())}>
